using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace PureMarkup.Maui.Generators;

/// <summary>
/// Emits fluent extension methods for MAUI types named by <c>[assembly: GenerateMarkup(...)]</c>.
/// Pipeline: compilation symbols -> equatable <see cref="MarkupModel"/> -> one source file per type.
/// </summary>
[Generator(LanguageNames.CSharp)]
public sealed class MarkupGenerator : IIncrementalGenerator
{
    private const string AttributeSource = """
        // <auto-generated/>
        #nullable enable

        namespace PureMarkup.Maui
        {
            /// <summary>
            /// Generates fluent markup extension methods for <see cref="Type"/> (or, with
            /// <see cref="WholeAssembly"/>, for every public type in its assembly).
            /// </summary>
            [global::System.AttributeUsage(global::System.AttributeTargets.Assembly, AllowMultiple = true)]
            [global::System.Diagnostics.Conditional("PUREMARKUP_KEEP_ATTRIBUTES")]
            internal sealed class GenerateMarkupAttribute : global::System.Attribute
            {
                public GenerateMarkupAttribute(global::System.Type type) => Type = type;

                /// <summary>The type to generate methods for.</summary>
                public global::System.Type Type { get; }

                /// <summary>Generate for every public type in the assembly that declares <see cref="Type"/>.</summary>
                public bool WholeAssembly { get; set; }

                /// <summary>Namespace of the generated classes. Default: PureMarkup.Maui.</summary>
                public string? Namespace { get; set; }
            }
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static ctx =>
            ctx.AddSource("GenerateMarkupAttribute.g.cs", SourceText.From(AttributeSource, System.Text.Encoding.UTF8)));

        // TODO: CompilationProvider re-runs the symbol walk on every edit; the equatable model keeps
        // emission cached. Narrow the trigger to assembly-attribute changes if consumer-time use grows.
        var model = context.CompilationProvider.Select(static (compilation, ct) => ModelBuilder.Build(compilation, ct));

        var types = model.SelectMany(static (m, _) => m.Types);
        context.RegisterSourceOutput(types, static (spc, type) =>
            spc.AddSource(type.ClassName + ".g.cs", SourceText.From(Emitter.Emit(type), System.Text.Encoding.UTF8)));

        var diagnostics = model.Select(static (m, _) => m.Diagnostics);
        context.RegisterSourceOutput(diagnostics, static (spc, items) =>
        {
            foreach (var item in items)
            {
                var descriptor = Diagnostics.Find(item.Id);
                if (descriptor is not null)
                {
                    spc.ReportDiagnostic(Diagnostic.Create(descriptor, Location.None, item.Args.Cast<object>().ToArray()));
                }
            }
        });
    }
}
